"""Official author, speaker and media resources; maintained together for consistent bios."""

def render_pages(g):
    g['KNOWS_ABOUT'][:] = [x for x in g['KNOWS_ABOUT'] if 'real estate' not in x.lower()]
    bio = 'Dr. Connor Robertson is an entrepreneur, author, and host of The Prospecting Show. His work covers sales conversations, prospecting, business systems, and entrepreneurship. He is the founder of Elixir Consulting Group and The Pittsburgh Wire and is based in Pittsburgh, Pennsylvania.'
    links = '<nav aria-label="Author resources"><a href="/about/">Biography</a> · <a href="/books/">Books</a> · <a href="/speaker/">Speaking</a> · <a href="/press-media/">Press</a> · <a href="/media/">Media kit</a> · <a href="https://www.prospectingshow.com/">The Prospecting Show</a></nav>'
    reading = '<h2>Choose a book by the problem you want to solve</h2><h3>The 7 Minute Phone Call</h3><p>For readers working on sales conversations and stalled opportunities. Use it alongside a review of your follow-up process: what is unresolved, who owns the next step, and what decision should the next conversation support?</p><p><a href="/books/the-7-minute-phone-call/">Explore The 7 Minute Phone Call</a> · <a href="https://www.7minutephonecallbook.com/">Book website</a></p><h3>Built to Run</h3><p>For owners developing business systems and reducing dependence on their personal involvement. Start by identifying one recurring handoff, documenting the expected result, and assigning an owner before adding more software.</p><p><a href="/books/built-to-run/">Explore Built to Run</a> · <a href="https://www.builttorunbook.com/">Book website</a></p><h3>Creative Acquisitions</h3><p>For readers exploring business acquisitions and deal structure. Separate the operating business, the seller’s objectives, and the buyer’s capacity to execute. Treat examples as prompts for further investigation rather than promises of a particular result.</p><p><a href="/books/creative-acquisitions/">Explore Creative Acquisitions</a></p>'
    pages = {
      '/about/': ('Dr. Connor Robertson | Official Biography', 'Official biography of Dr. Connor Robertson, author, entrepreneur and host of The Prospecting Show, with books, speaking and media resources.', '<h1>Dr. Connor Robertson</h1><p>'+bio+'</p><h2>Author and podcast host</h2><p>His books include <em>The 7 Minute Phone Call</em>, <em>Built to Run</em>, and <em>Creative Acquisitions</em>. Together, these titles address sales conversations, operational systems, and buying businesses.</p><p>On <a href="https://www.prospectingshow.com/">The Prospecting Show</a>, Connor interviews entrepreneurs and business professionals about prospecting, sales, and building companies. The <a href="https://www.prospectingshow.com/blog/sales-playbooks/">sales playbook library</a> provides practical frameworks and illustrative examples for sales teams.</p><h2>Background and professional title</h2><p>Connor’s educational background includes Western University and New York Chiropractic College. The title “Dr.” refers to his chiropractic education. This website presents his business, publishing, and media work.</p><h2>For readers, event organizers, and journalists</h2><p>Use the book guide to choose a starting point, the speaking page to discuss an event, and the media kit for an introduction and approved portrait links.</p>'),
      '/books/': ('Books by Dr. Connor Robertson | Selected Reading Guide', 'Explore selected books by Dr. Connor Robertson on sales conversations, business systems and business acquisitions, with a practical reading guide.', '<h1>Books by Dr. Connor Robertson</h1><p>A selected reading guide for sales professionals, entrepreneurs, and business owners. Choose a topic that matches a current decision, then turn the reading into a small, observable change in your workflow.</p>'+reading+'<h2>Read, discuss, apply</h2><p>For a team discussion, ask each reader to bring one example from the current pipeline or operating process. Agree on a single change, a responsible person, and a review date. Compare what happened with what the team expected before extending the change.</p><p><a href="https://www.drconnorrobertsonbooks.com/">Visit the author’s book catalog</a> for additional book information.</p>'),
      '/speaker/': ('Dr. Connor Robertson | Speaker on Sales & Business Systems', 'Explore speaking topics for Dr. Connor Robertson: prospecting, sales conversations, founder-led operations and practical business systems.', '<h1>Dr. Connor Robertson — Speaking</h1><p>Speaking and interview topics for sales teams, founder communities, business podcasts, and entrepreneurship events. Use the outlines below as a starting point for a conversation about your audience and format.</p><h2>Prospecting with a clear next step</h2><p>How teams can connect account research, outreach, and follow-up to a specific customer problem. Discussion points include account selection, relevant opening questions, and recording the next agreed action.</p><p>Audience takeaway: a way to review outreach quality beyond counting activities. Useful formats include a workshop, moderated conversation, or team discussion.</p><h2>Better conversations when a sale stalls</h2><p>A discussion of uncertainty in the sales process: missing stakeholders, unclear timing, unresolved questions, and next steps that have no owner. Connect the session with <a href="/books/the-7-minute-phone-call/">The 7 Minute Phone Call</a> and bring anonymized examples for discussion.</p><h2>From founder knowledge to repeatable systems</h2><p>How to make recurring work visible, define a handoff, and give a process an accountable owner. A session can focus on one operating workflow and the information needed to run it consistently. Related reading: <a href="/books/built-to-run/">Built to Run</a>.</p><h2>Plan a speaking inquiry</h2><p>Include your event date, location or virtual platform, audience, preferred topic, session length, and organizer contact. Availability, format, and terms are confirmed during planning.</p><p><a href="/contact/">Send a speaking inquiry</a> · <a href="/media/">Find a speaker introduction and portraits</a></p>'),
      '/press-media/': ('Dr. Connor Robertson | Press & Interview Resources', 'Press resources for Dr. Connor Robertson: biography, interview topics, linked coverage, company announcements and media contact information.', '<h1>Dr. Connor Robertson — Press & Interviews</h1><p>'+bio+'</p><h2>Interview angles</h2><ul><li>What a useful next step looks like in a prospecting conversation.</li><li>How founders document recurring decisions and hand off work.</li><li>Turning business books into team discussion and operating experiments.</li><li>Lessons and questions from hosting entrepreneurial conversations.</li></ul><h2>Profiles and coverage</h2><p><a href="https://gritdaily.com/dr-connor-robertson-entrepreneur-author-and-founder/">Grit Daily: entrepreneur, author and founder profile</a>. Read each source for its publication context and claims.</p><h2>Company announcements</h2><p>The Elixir Consulting Group business automation advisory announcement appears on <a href="https://finance.yahoo.com/sectors/technology/articles/elixir-consulting-group-launches-business-112900872.html">Yahoo Finance</a> and <a href="https://markets.businessinsider.com/news/stocks/elixir-consulting-group-launches-business-automation-advisory-service-for-small-and-midsized-business-owners-1036100299">Markets Insider</a>. These are company announcements; their distribution does not imply an editorial endorsement.</p><h2>Prepare an interview</h2><p>Send the outlet, topic, deadline, recording format, and intended publication date through the <a href="/contact/">contact page</a>. Use the <a href="/media/">media kit</a> for a short biography, introduction, and portrait links. Book-specific questions can begin with the <a href="/books/">selected reading guide</a>.</p>'),
      '/media/': ('Dr. Connor Robertson | Official Media Kit & Biography', 'Official media kit for Dr. Connor Robertson with a reusable biography, speaker introduction, portraits, books and interview resources.', '<h1>Dr. Connor Robertson — Media Kit</h1><p>Resources for event organizers, podcast producers, and journalists. Confirm current event details and any publication-specific questions through the contact page.</p><h2>Short biography</h2><blockquote>'+bio+'</blockquote><h2>Speaker introduction</h2><blockquote>Our guest is Dr. Connor Robertson, an entrepreneur, author, and host of The Prospecting Show. His books and conversations explore prospecting, sales, business systems, and entrepreneurship.</blockquote><h2>Name and title</h2><p>Use “Dr. Connor Robertson” on first reference and “Connor Robertson” or “Robertson” afterward according to your editorial style. His professional title reflects chiropractic education; this kit concerns his business and author work.</p><h2>Portraits</h2><p><a href="/images/connor-headshot.jpg">Download headshot</a> · <a href="/images/connor-about.jpg">Download author portrait</a></p><p>Credit: Dr. Connor Robertson. These portraits are provided for editorial coverage and event promotion featuring Connor. Contact the team for other uses or additional files.</p><h2>Book and interview preparation</h2><p><a href="/books/">Selected books and reading guide</a> · <a href="/speaker/">Speaking topics</a> · <a href="/press-media/">Press and interview resources</a> · <a href="/contact/">Media inquiries</a></p>')
    }
    result={}
    style='<style>.asset-page{max-width:880px;margin:auto;padding:48px 24px}.asset-page h1{font-size:clamp(32px,5vw,54px);line-height:1.15}.asset-page h2{margin-top:36px}.asset-page h3{margin-top:26px}.asset-page p,.asset-page li,.asset-page blockquote{font-size:18px;line-height:1.8}.asset-page a{text-decoration:underline}.asset-page nav{line-height:2;margin:24px 0}.asset-page blockquote{border-left:4px solid #b89b67;padding:16px;margin:16px 0;background:#f5f5f5;color:#222}</style>'
    for route,(title,desc,body) in pages.items():
        result[route]=g['header'](title,desc,route,extra=style,og_image='/images/connor-headshot.jpg',page_type='ProfilePage' if route=='/about/' else 'WebPage',page_extra={'dateModified':'2026-10-12','about':{'@id':g['PERSON_ID']}})+'<article class="asset-page">'+links+body+links+'</article>'+g['footer']()
        result[route]=result[route].replace('Pittsburgh business and real estate publication','Pittsburgh business publication')
    return result
